// Daily prediction caption builder.
//
// Matches the bilingual template the user approved:
//   📢 ScoreOcs8 Today's Predictions | 今日足球精选预测
//   📅 21 April 2026
//
//   Today's top pro picks | 今日推介:
//   👉 🏆 UCL · Man City vs Arsenal — Man City win @1.85
//   ...
//
//   📊 Accuracy this week | 本周准确率: 8/12 (67%)
//
//   View all today's predictions | 浏览更多推介:
//   👉 https://scoreocs8.com/
//
//   🎁 Claim welcome bonus | 领取新手礼金:
//   👉 🇲🇾 https://[affiliate-my]
//   👉 🇸🇬 https://[affiliate-sg]
//
//   #ScoreOcs8 #footballpredictions #ProPicks #足球预测 #今日推介

const LEAGUE_EMOJI = {
  39: '🏴󠁧󠁢󠁥󠁮󠁧󠁿',
  2: '⭐',
  1: '🏆',
  140: '🇪🇸',
  78: '🇩🇪',
  135: '🇮🇹',
  61: '🇫🇷',
};

// Short codes to keep caption compact (Telegram captions cap at 1024 chars).
const LEAGUE_SHORT = {
  39: 'EPL',
  2: 'UCL',
  1: 'WC',
  140: 'LaLiga',
  78: 'BL',
  135: 'Serie A',
  61: 'Ligue 1',
};

// HTML escape for Telegram parse_mode=HTML.
function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function fmtDate(ymd) {
  const d = new Date(ymd + 'T12:00:00Z');
  return d.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Kuala_Lumpur',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
}

export function buildDailyCaption({
  date,
  picks = [],
  accuracy = null,
  siteUrl = 'https://scoreocs8.com',
  affiliates = [],
}) {
  const lines = [];
  lines.push(`📢 <b>ScoreOcs8 Today's Predictions</b> | 今日足球精选预测`);
  lines.push(`📅 ${esc(fmtDate(date))}`);
  lines.push('');

  if (picks.length) {
    lines.push(`<b>Today's top pro picks</b> | 今日推介:`);
    for (const p of picks.slice(0, 3)) {
      const leagueId = p.fx?.league?.id;
      const flag = LEAGUE_EMOJI[leagueId] || '⚽';
      const league = LEAGUE_SHORT[leagueId] || (p.fx?.league?.name || '');
      const home = p.fx?.teams?.home?.name || 'Home';
      const away = p.fx?.teams?.away?.name || 'Away';
      const pickLabel = p.pick?.pickLabel || p.pick?.pick || 'Pro analysis pending';
      const conf = p.pick?.confidence != null ? ` (${p.pick.confidence}%)` : '';
      lines.push(`👉 ${flag} <b>${esc(league)}</b> · ${esc(home)} vs ${esc(away)} — <b>${esc(pickLabel)}</b>${conf}`);
    }
    lines.push('');
  }

  if (accuracy && accuracy.total > 0) {
    lines.push(
      `📊 <b>Accuracy this week</b> | 本周准确率: ${accuracy.hits}/${accuracy.total} (${accuracy.pct}%)`
    );
    lines.push('');
  }

  lines.push(`🔗 <b>View all predictions</b> | 浏览更多推介:`);
  lines.push(`👉 ${siteUrl}/`);
  lines.push('');

  // Always include the OCS8 Sports signup CTA — single source of truth for
  // the affiliate funnel from Telegram captions.
  lines.push(`🆕 <b>Sign up · OCS8 Sports</b> | 立即注册:`);
  lines.push(`👉 https://ocs8my.com/signup?ref=OCSFMZ6HVI`);
  lines.push('');

  if (affiliates.length) {
    lines.push(`🎁 <b>Welcome bonus</b> | 领取新手礼金:`);
    for (const a of affiliates) {
      lines.push(`👉 ${a.flag || ''} ${a.url}`);
    }
    lines.push('');
  }

  lines.push(
    `#ScoreOcs8 #footballpredictions #ProPicks #malaysianfootball #足球预测 #今日推介`
  );

  const out = lines.join('\n');
  // Telegram caption hard limit is 1024 chars — truncate defensively.
  return out.length > 1020 ? out.slice(0, 1017) + '...' : out;
}

// Compact variant for X / Twitter — 280 char hard limit, URLs count as 23.
export function buildDailyCaptionX({
  date,
  picks = [],
  accuracy = null,
  siteUrl = 'https://scoreocs8.com',
}) {
  const d = new Date(date + 'T12:00:00Z').toLocaleDateString('en-GB', {
    timeZone: 'Asia/Kuala_Lumpur',
    day: 'numeric', month: 'short',
  });
  const lines = [];
  lines.push(`📢 ScoreOcs8 Top Pro Picks · ${d}`);
  lines.push('');
  for (const p of picks.slice(0, 3)) {
    const leagueId = p.fx?.league?.id;
    const flag = LEAGUE_EMOJI[leagueId] || '⚽';
    const short = LEAGUE_SHORT[leagueId] || '';
    const home = p.fx?.teams?.home?.name || 'Home';
    const away = p.fx?.teams?.away?.name || 'Away';
    const pickLabel = p.pick?.pickLabel || p.pick?.pick || '—';
    const conf = p.pick?.confidence != null ? ` (${p.pick.confidence}%)` : '';
    lines.push(`${flag} ${short} · ${home} vs ${away} → ${pickLabel}${conf}`);
  }
  if (accuracy && accuracy.total > 0) {
    lines.push('');
    lines.push(`📊 Weekly: ${accuracy.hits}/${accuracy.total} (${accuracy.pct}%)`);
  }
  lines.push('');
  lines.push(`🔗 ${siteUrl}/`);
  lines.push('#football #ProPicks');

  let out = lines.join('\n');
  // X counts URLs as 23 chars regardless of length; approximate by subtracting
  // real URL length then adding 23 when checking budget.
  const urlCount = (out.match(/https?:\/\/[^\s]+/g) || []).length;
  const effective = out.length + (urlCount > 0 ? 23 - 22 : 0); // scoreocs8.com/ = ~22 chars, X counts as 23 — add 1 per URL
  if (effective > 275) {
    // Drop the 3rd pick first, then hashtags, then accuracy line
    const trimmed = out.split('\n').filter((l, i, arr) => {
      if (i === arr.findIndex(x => x.startsWith('#'))) return false;
      return true;
    }).join('\n');
    out = trimmed.length > 275 ? trimmed.slice(0, 275) : trimmed;
  }
  return out;
}

// Threads variant — 500 char limit, between X and full caption.
export function buildDailyCaptionThreads(opts) {
  const full = buildDailyCaption(opts);
  return full.length > 495 ? full.slice(0, 492) + '...' : full;
}

// Instagram variant — reuse full caption, IG allows 2200 chars so ours fits.
export const buildDailyCaptionIG = buildDailyCaption;

// Pre-match caption for the Match of the Day virtual bet slip. Posted
// shortly after the daily predictions fan-out so the channel gets:
//   1) the list of 3 picks (daily),
//   2) the featured bet slip for the top match with RM100 virtual stake.
export function buildPreMatchMotdCaption({
  fixture,
  pick,
  stake = 100,
  siteUrl = 'https://scoreocs8.com',
}) {
  const home = fixture?.teams?.home?.name || 'Home';
  const away = fixture?.teams?.away?.name || 'Away';
  const leagueId = fixture?.league?.id;
  const flag = LEAGUE_EMOJI[leagueId] || '⚽';
  const league = LEAGUE_SHORT[leagueId] || fixture?.league?.name || '';
  const conf = pick?.confidence ?? 50;
  // Same odds curve as the /slip/ page so caption matches the graphic.
  const odds = +(1 + (1 - conf / 100) * 2.5).toFixed(2);
  const payout = +(stake * odds).toFixed(2);
  const selection = pick?.pickLabel || pick?.pick || 'Pro analysis pending';

  let kickoff = '—';
  try {
    kickoff = new Date(fixture.fixture.date).toLocaleTimeString('en-MY', {
      timeZone: 'Asia/Kuala_Lumpur', hour: '2-digit', minute: '2-digit', hour12: false,
    });
  } catch {}

  const lines = [];
  lines.push(`🎫 <b>Match of the Day</b> · 今日重点推介`);
  lines.push(`${flag} <b>${esc(league)}</b>`);
  lines.push('');
  lines.push(`⚽ <b>${esc(home)} vs ${esc(away)}</b>`);
  lines.push(`⏰ Kickoff: ${esc(kickoff)} MYT`);
  lines.push('');
  lines.push(`⚡ <b>Pro Pick</b>: ${esc(selection)} (${conf}%)`);
  lines.push(`💰 Virtual stake · 虚拟注码: <b>RM${esc(stake)}</b>`);
  lines.push(`💵 Potential payout · 潜在回报: <b>RM${esc(payout.toFixed(2))}</b> @${esc(odds)}`);
  lines.push('');
  lines.push(`🔗 Live tracking: ${siteUrl}/`);
  lines.push('');
  lines.push(`⚠ 18+`);
  lines.push(`#MatchOfTheDay #ScoreOcs8 #足球预测`);
  return lines.join('\n');
}

// Lightweight pre-match update used for full World Cup coverage. Unlike
// buildPreMatchMotdCaption (which frames a virtual bet slip around a pro
// pick), this posts a clean "kicking off soon" card — teams, kickoff in MYT,
// venue — with no AI-pick framing, so every WC match gets a neutral alert.
export function buildMatchUpdateCaption({ fixture, siteUrl = 'https://scoreocs8.com' }) {
  const home = fixture?.teams?.home?.name || 'Home';
  const away = fixture?.teams?.away?.name || 'Away';
  const leagueId = fixture?.league?.id;
  const flag = LEAGUE_EMOJI[leagueId] || '⚽';
  const league = LEAGUE_SHORT[leagueId] || fixture?.league?.name || '';
  const venue = fixture?.fixture?.venue?.name || '';
  const city = fixture?.fixture?.venue?.city || '';

  let kickoff = '—';
  try {
    kickoff = new Date(fixture.fixture.date).toLocaleTimeString('en-MY', {
      timeZone: 'Asia/Kuala_Lumpur', hour: '2-digit', minute: '2-digit', hour12: false,
    });
  } catch {}

  const lines = [];
  lines.push(`⏰ <b>Kicking off soon · 即将开赛</b>`);
  lines.push(`${flag} <b>${esc(league)}</b>`);
  lines.push('');
  lines.push(`⚽ <b>${esc(home)} vs ${esc(away)}</b>`);
  lines.push(`🕐 Kickoff · 开赛: ${esc(kickoff)} MYT`);
  if (venue) lines.push(`🏟️ ${esc(venue)}${city ? ', ' + esc(city) : ''}`);
  lines.push('');
  lines.push(`🔗 Live tracking · 实时追踪: ${siteUrl}/`);
  lines.push('');
  lines.push(`🆕 <b>Sign up · OCS8 Sports</b> | 立即注册:`);
  lines.push(`👉 https://ocs8my.com/signup?ref=OCSFMZ6HVI`);
  lines.push('');
  lines.push(`⚠ 18+`);
  lines.push(`#WorldCup2026 #ScoreOcs8 #足球预测`);
  return lines.join('\n');
}

// Caption for match result posts: "FT · Team A 2-1 Team B"
export function buildResultCaption({ fixture, pickCorrect = null, weekAcc = null, siteUrl = 'https://scoreocs8.com' }) {
  const home = fixture?.teams?.home?.name || 'Home';
  const away = fixture?.teams?.away?.name || 'Away';
  const hs = fixture?.goals?.home ?? '-';
  const as = fixture?.goals?.away ?? '-';
  const leagueId = fixture?.league?.id;
  const flag = LEAGUE_EMOJI[leagueId] || '⚽';
  const league = LEAGUE_SHORT[leagueId] || fixture?.league?.name || '';

  const lines = [];
  lines.push(`⚽ <b>FULL-TIME</b> | 比赛结束`);
  lines.push(`${flag} <b>${esc(league)}</b>`);
  lines.push('');
  lines.push(`<b>${esc(home)} ${hs} — ${as} ${esc(away)}</b>`);
  lines.push('');
  if (pickCorrect === true) lines.push(`✅ Our pro pick was <b>correct</b> · 预测正确`);
  else if (pickCorrect === false) lines.push(`❌ Our pro pick missed · 预测未中`);
  if (weekAcc && weekAcc.total > 0) {
    lines.push(`📊 This week: ${weekAcc.hits}/${weekAcc.total} (${weekAcc.pct}%)`);
  }
  lines.push('');
  lines.push(`🔗 Full analysis | 完整分析: ${siteUrl}/`);
  lines.push('');
  lines.push(`🆕 <b>Sign up · OCS8 Sports</b> | 立即注册:`);
  lines.push(`👉 https://ocs8my.com/signup?ref=OCSFMZ6HVI`);
  lines.push('');
  lines.push(`#ScoreOcs8 #${esc(league).replace(/\s+/g, '')} #足球预测`);

  return lines.join('\n');
}

