// Minimal Telegram Bot API wrapper for sending photos + text to channels.
//
// Required env vars:
//   env.TG_BOT_TOKEN    - bot token from BotFather (bot MUST be admin of
//                         target channel with "Post Messages" permission)
//   env.TG_CHANNEL_ID   - either @public_username or numeric -100... id

const TG_API = 'https://api.telegram.org';

// Global kill-switch: KV tg:posting = 'off' silences the channel without
// touching credentials (set while repositioning content, e.g. WC focus).
// Missing key or any other value = posting ON. Senders return
// { disabled: true } instead of throwing so cron jobs proceed quietly and
// mark their events handled rather than retrying them forever.
async function postingOff(env) {
  try { return (await env.CACHE?.get('tg:posting')) === 'off'; } catch { return false; }
}

// sendPhoto with PNG bytes as multipart form data.
// Returns Telegram's message object on success.
export async function sendPhoto(env, { photoBytes, caption, parseMode = 'HTML' }) {
  if (await postingOff(env)) return { disabled: true };
  assertCreds(env);

  const form = new FormData();
  form.append('chat_id', env.TG_CHANNEL_ID);
  form.append('parse_mode', parseMode);
  if (caption) form.append('caption', caption);
  form.append(
    'photo',
    new Blob([photoBytes], { type: 'image/png' }),
    'daily.png'
  );

  const res = await fetch(`${TG_API}/bot${env.TG_BOT_TOKEN}/sendPhoto`, {
    method: 'POST',
    body: form,
  });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) {
    throw new Error(
      `Telegram sendPhoto failed ${data.error_code || res.status}: ${data.description || 'unknown'}`
    );
  }
  return data.result;
}

// sendMessage for text-only posts (polls, accuracy tracker, etc.).
export async function sendMessage(env, { text, parseMode = 'HTML', disablePreview = false }) {
  if (await postingOff(env)) return { disabled: true };
  assertCreds(env);

  const res = await fetch(`${TG_API}/bot${env.TG_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: env.TG_CHANNEL_ID,
      text,
      parse_mode: parseMode,
      disable_web_page_preview: disablePreview,
    }),
  });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) {
    throw new Error(
      `Telegram sendMessage failed ${data.error_code || res.status}: ${data.description || 'unknown'}`
    );
  }
  return data.result;
}

// sendPoll for anonymous fan polls (e.g., 12h pre-match "Who wins?").
// Telegram poll API: question max 300 chars, 2-10 options, each max 100 chars.
export async function sendPoll(env, { question, options, isAnonymous = true }) {
  if (await postingOff(env)) return { disabled: true };
  assertCreds(env);
  if (!Array.isArray(options) || options.length < 2 || options.length > 10) {
    throw new Error(`sendPoll needs 2-10 options, got ${options?.length}`);
  }
  const res = await fetch(`${TG_API}/bot${env.TG_BOT_TOKEN}/sendPoll`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: env.TG_CHANNEL_ID,
      question: String(question || '').slice(0, 300),
      options: options.map(o => String(o || '').slice(0, 100)),
      is_anonymous: !!isAnonymous,
      type: 'regular',
      allows_multiple_answers: false,
    }),
  });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) {
    throw new Error(
      `Telegram sendPoll failed ${data.error_code || res.status}: ${data.description || 'unknown'}`
    );
  }
  return data.result;
}

function assertCreds(env) {
  if (!env.TG_BOT_TOKEN || !env.TG_CHANNEL_ID) {
    throw new Error('TG_BOT_TOKEN and TG_CHANNEL_ID must be set');
  }
}
